[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$WorkRoot,
    [Parameter(Mandatory)][string]$Zig,
    # The declaration contract the generated Zig tables import; defaults to the controller module's own copy.
    [string]$Contract = (Join-Path (Split-Path -Parent $PSScriptRoot) 'src/Shared/Control/src/declarations.zig'),
    # Optional: production C# generated by the generator before a change (<process>.before.cs). Given, the
    # suite proves the change left the production C# output byte-identical; omitted, that comparison is skipped.
    [string]$CSharpBaselineDirectory
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent $PSScriptRoot
Import-Module (Join-Path $repo 'scripts/build/StateItemRegistry.psm1') -Force
$tool = Join-Path $repo 'scripts/tools/Manage-StateItems.ps1'
$generator = Join-Path $repo 'scripts/build/Generate-StateItems.ps1'
$script:count = 0
function Assert-True([bool]$Value, [string]$Reason) {
    if (-not $Value) { throw "Assertion failed: $Reason" }
    $script:count++
}
function Assert-Rejected([scriptblock]$Operation, [string]$Reason) {
    $caught = $null
    try { & $Operation | Out-Null } catch { $caught = $_.Exception.Message }
    Assert-True ($null -ne $caught -and $caught -match $Reason) "Expected /$Reason/, got: $caught"
}
function Get-Fixture {
    ConvertFrom-Json -AsHashtable @'
{"entries":[
{"uid":1,"kind":"block","process":"backend","name":"Program","comment":"Backend root."},
{"uid":2,"kind":"block","process":"ui","name":"Program","comment":"UI root."},
{"uid":3,"kind":"block","process":"backend","name":"Worker","comment":"Backend child."},
{"uid":4,"kind":"block","process":"backend","name":"OtherNode","comment":"Another node."},
{"uid":5,"kind":"block","process":"ui","name":"Window","comment":"UI child."},
{"uid":6,"kind":"item","process":"backend","name":"Ready","comment":"Ready café 中文 \"quote\" \\path.\nLine.","storage":"reference","type":"bool","owner":{"block":1},"perBlock":false,"trigger":"event","changeEvent":"Fixture owner transition"},
{"uid":7,"kind":"item","process":"backend","name":"Demand","comment":"Demand by block.","storage":"own","type":"bool","owner":{"component":"Demand holder"},"perBlock":true,"trigger":"poll","pollInterval":"/fixture/interval"},
{"uid":8,"kind":"item","process":"ui","name":"Visible","comment":"Window desired.","storage":"own","type":"bool","owner":{"component":"UI owner"},"perBlock":false,"trigger":"event","changeEvent":"Fixture owner transition"},
{"uid":9,"kind":"item","process":"ui","name":"Demand","comment":"UI demand.","storage":"reference","type":"bool","owner":{"block":2},"perBlock":true,"trigger":"event","changeEvent":"Fixture owner transition"},
{"uid":10,"kind":"condition","process":"backend","name":"Available","comment":"Lower condition.","node":1,"perBlock":false,"items":[{"item":6},{"block":3,"item":7}],"conditions":[],"children":[]},
{"uid":11,"kind":"condition","process":"backend","name":"ShouldRun","comment":"Top condition.","node":1,"perBlock":false,"items":[],"conditions":[10],"children":[3],"decides":3},
{"uid":12,"kind":"condition","process":"backend","name":"defer","comment":"Per-block implicit key.","perBlock":true,"items":[{"item":7}],"conditions":[],"children":[]},
{"uid":13,"kind":"condition","process":"backend","name":"ExplicitBlock","comment":"Per-block explicit key and global item.","perBlock":true,"items":[{"item":7,"block":3},{"item":6}],"conditions":[],"children":[]},
{"uid":14,"kind":"condition","process":"ui","name":"Available","comment":"UI lower.","node":2,"perBlock":false,"items":[{"item":8},{"item":9,"block":5}],"conditions":[],"children":[]},
{"uid":15,"kind":"condition","process":"ui","name":"ShouldRun","comment":"UI top.","node":2,"perBlock":false,"items":[],"conditions":[14],"children":[5],"decides":5},
{"uid":16,"kind":"condition","process":"ui","name":"Always","comment":"Per-block no items.","perBlock":true,"items":[],"conditions":[],"children":[]}
]}
'@
}
function Assert-Invalid([scriptblock]$Change, [string]$Reason) {
    $table = Get-Fixture
    & $Change $table
    $bytes = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $table -Depth 12 -Compress))
    Assert-Rejected { Read-StateRegistry -Bytes $bytes } $Reason
}
$marker = Join-Path $WorkRoot '.generated-workspace.json'
if (-not (Test-Path -LiteralPath $marker) -or (Get-Content $marker -Raw | ConvertFrom-Json).state -ne 'running') {
    throw 'WorkRoot must be a running registered task.'
}
$zigVersion = & $Zig version
if ($LASTEXITCODE -ne 0 -or $zigVersion -cne '0.17.0') { throw 'These contract tests require Zig 0.17.0.' }
$scratch = Join-Path ([IO.Path]::GetFullPath($WorkRoot)) ('conditions-' + [guid]::NewGuid().ToString('N'))
$null = [IO.Directory]::CreateDirectory($scratch)
$path = Join-Path $scratch 'registry.json'
Write-StateRegistry $path (Get-Fixture)
$bytes = [IO.File]::ReadAllBytes($path)
$read = Read-StateRegistry -Path $path
Assert-True ([Convert]::ToBase64String($bytes) -ceq [Convert]::ToBase64String((ConvertTo-StateRegistryBytes $read))) 'Condition registry round-trips byte for byte.'
Assert-True (-not ($bytes -contains [byte]13) -and $bytes[0] -eq 123 -and $bytes[-1] -eq 10) 'Canonical LF, UTF-8 without BOM, final LF.'
$read.entries[9].items[1] = [ordered]@{ block=3; item=7 }
Assert-True ([Convert]::ToBase64String($bytes) -ceq [Convert]::ToBase64String((ConvertTo-StateRegistryBytes $read))) 'Nested item read fields have canonical ordering.'

foreach ($field in @('node','items','conditions','children','decides')) {
    foreach ($index in @(0,5)) { Assert-Invalid { param($r) $r.entries[$index][$field]=1 } "unknown field $field" }
}
foreach ($field in @('storage','type','owner','trigger','pollInterval','extra')) {
    Assert-Invalid { param($r) $r.entries[9][$field]='x' } "unknown field $field"
}
foreach ($field in @('perBlock','items','conditions','children')) {
    Assert-Invalid { param($r) $null=$r.entries[9].Remove($field) } "missing $field"
}
Assert-Invalid { param($r) $null=$r.entries[9].Remove('node') } 'non-per-block condition requires node'
Assert-Invalid { param($r) $r.entries[9].perBlock='false' } 'perBlock must be boolean'
foreach ($field in @('items','conditions','children')) {
    Assert-Invalid { param($r) $r.entries[9][$field]=@{} } "$field must be an array"
}
foreach ($field in @('node','decides')) {
    foreach ($value in @(0,4294967296L,'1',$true,$null,1.5)) { Assert-Invalid { param($r) $r.entries[9][$field]=$value } "$field.*uid must be an integer from 1 to 4294967295" }
}
foreach ($value in @($null,1,@{},@{block=3})) { Assert-Invalid { param($r) $r.entries[9].items=@($value) } 'items read must contain item and optional block' }
Assert-Invalid { param($r) $r.entries[9].items=@(@{item=6;extra=3}) } 'unknown item read field extra'
Assert-Invalid { param($r) $r.entries[9].items=@(@{item='6'}) } 'items.item.*uid must be an integer'
Assert-Invalid { param($r) $r.entries[9].items=@(@{item=7;block=$null}) } 'items.block.*uid must be an integer'
foreach ($field in @('conditions','children')) { Assert-Invalid { param($r) $r.entries[9][$field]=@('3') } "$field.*uid must be an integer" }
# Missing UID, wrong kind and other process at every reference position.
foreach ($uid in @(99,6,2)) { Assert-Invalid { param($r) $r.entries[9].node=$uid } 'node must reference an existing block in the same process' }
foreach ($uid in @(99,6,2)) { Assert-Invalid { param($r) $r.entries[10].decides=$uid } 'decides must reference an existing block in the same process' }
foreach ($uid in @(99,1,8)) { Assert-Invalid { param($r) $r.entries[9].items=@(@{item=$uid}) } 'items.item must reference an existing item in the same process' }
foreach ($uid in @(99,6,2)) { Assert-Invalid { param($r) $r.entries[9].items=@(@{item=7;block=$uid}) } 'items.block must reference an existing block in the same process' }
foreach ($uid in @(99,6,2)) { Assert-Invalid { param($r) $r.entries[10].children=@($uid) } 'children must reference an existing block in the same process' }
foreach ($uid in @(99,6,14)) { Assert-Invalid { param($r) $r.entries[10].conditions=@($uid) } 'conditions must reference an existing condition in the same process' }
Assert-Invalid { param($r) $r.entries[9].items=@(@{item=7}) } 'per-block item read requires block outside a per-block condition'
Assert-Invalid { param($r) $r.entries[9].items=@(@{item=6;block=3}) } 'items.block is allowed only for a per-block item'
Assert-Invalid { param($r) $r.entries[9].node=4 } 'lower conditions must belong to the same node'
Assert-Invalid { param($r) $r.entries[10].conditions=@(12) } 'lower conditions must belong to the same node'
Assert-Invalid { param($r) $r.entries[9].conditions=@(10) } 'condition cycle in node 1'
Assert-Invalid { param($r) $r.entries[9].conditions=@(11) } 'condition cycle in node 1'
foreach ($field in @('node','decides')) {
    Assert-Invalid { param($r) $r.entries[11][$field]=1 } 'per-block condition must omit node and decides'
    Assert-Invalid { param($r) $r.entries[11][$field]=$null } 'per-block condition must omit node and decides'
}
Assert-Invalid { param($r) $r.entries[11].conditions=@(10) } 'per-block condition reads items only'
Assert-Invalid { param($r) $r.entries[11].children=@(3) } 'per-block condition reads items only'
Assert-Invalid { param($r) $r.entries[11].items=@(@{item=6;block=3}) } 'items.block is allowed only for a per-block item'
Assert-Invalid { param($r) $r.entries[11].items=@(@{item=7;block=5}) } 'items.block must reference an existing block in the same process'
$otherType = Get-Fixture
$otherType.entries[5].type='int'
Assert-StateRegistry $otherType
Assert-Invalid { param($r) $r.entries[1].process='other' } 'process must be backend, ui, desktop or window'
# The two UI processes after the split: the UI fixture moved to desktop or window validates and generates as it did under ui.
foreach ($uiProcess in @('desktop','window')) {
    $split = Get-Fixture
    foreach ($entry in $split.entries) { if ($entry.process -ceq 'ui') { $entry.process = $uiProcess } }
    Assert-StateRegistry $split
    $splitPath = Join-Path $scratch "registry-$uiProcess.json"
    Write-StateRegistry $splitPath $split
    $splitOutput = Join-Path $scratch "$uiProcess.zig"
    & (Join-Path $PSScriptRoot '../scripts/build/Generate-StateItems.ps1') -Registry $splitPath -Process $uiProcess -Language Zig -Names $true -Output $splitOutput
    Assert-True ([IO.File]::ReadAllText($splitOutput).Contains(".process = `"$uiProcess`"")) "Zig tables generate for process $uiProcess."
}

# Long chain proves iterative traversal and absence of the tree-only 64 limit here.
$chain = [Collections.Generic.List[object]]::new()
$chain.Add((Get-Fixture).entries[0])
for ($uid=2; $uid -le 2001; $uid++) {
    $deps = @()
    if ($uid -lt 2001) { $deps = @($uid+1) }
    $chain.Add(@{uid=$uid;kind='condition';process='backend';name="Chain$uid";comment='Chain';node=1;perBlock=$false;items=@();conditions=$deps;children=@()})
}
Assert-StateRegistry @{entries=$chain.ToArray()}
Assert-True $true 'Two thousand conditions validate without recursion or a registry-level 64 limit.'
$chain[$chain.Count-1].conditions=@(2)
Assert-Rejected { Assert-StateRegistry @{entries=$chain.ToArray()} } 'condition cycle in node 1'

$table=Get-Fixture
$table.entries=@($table.entries | Where-Object uid -NE 12)
Write-StateRegistry $path $table
$added=& $tool -Action Add -Registry $path -Kind condition -Process backend -Name Reused -Comment 'Reused condition.' -PerBlock $true -ItemReads @(@{item=7})
Assert-True ($added -eq 12) 'Add condition fills smallest gap.'
$added=& $tool -Action Add -Registry $path -Kind condition -Process backend -Name LowerAdded -Comment 'New lower.' -Node 1 -PerBlock $false -ItemReads @(@{item=7;block=3})
Assert-True ($added -eq 17) 'Add lower condition.'
$added=& $tool -Action Add -Registry $path -Kind condition -Process backend -Name TopAdded -Comment 'New top.' -Node 1 -PerBlock $false -Conditions @(17) -Children @(3) -Decides 3
Assert-True ($added -eq 18) 'Add top condition.'
$resolved=& $tool -Action Resolve -Registry $path -Uid 18 | ConvertFrom-Json
Assert-True ($resolved.kind -ceq 'condition' -and $resolved.conditions[0] -eq 17 -and $resolved.decides -eq 3) 'Resolve includes condition fields.'
$export=& $tool -Action Export -Registry $path -Destination (Join-Path $scratch 'tables')
$published=& $tool -Action Resolve -Registry $path -Uid 12 -Version (Get-StateRegistryVersion ([IO.File]::ReadAllBytes($path))) -TableDirectory (Join-Path $scratch 'tables') | ConvertFrom-Json
Assert-True ($published.kind -ceq 'condition' -and $published.perBlock) 'Export and versioned Resolve include conditions.'
$before=[Convert]::ToBase64String([IO.File]::ReadAllBytes($path))
Assert-Rejected { & $tool -Action Add -Registry $path -Kind condition -Process backend -Name Invalid -Comment 'Invalid.' -PerBlock $false -Node 8 } 'node must reference an existing block'
Assert-True ($before -ceq [Convert]::ToBase64String([IO.File]::ReadAllBytes($path))) 'Invalid condition Add leaves bytes unchanged.'

Write-StateRegistry $path (Get-Fixture)
[IO.File]::Copy([IO.Path]::GetFullPath($Contract), (Join-Path $scratch 'control-declarations.zig'))
[IO.File]::WriteAllText((Join-Path $scratch 'rm_control.zig'), 'pub const declarations = @import("control-declarations.zig");')
foreach ($process in @('backend','ui')) {
    foreach ($names in @($true,$false)) {
        $output=Join-Path $scratch "$process-$names.zig"
        & $generator -Registry $path -Process $process -Language Zig -Names $names -Output $output
        $source=[IO.File]::ReadAllText($output)
        $hash=(Get-FileHash $output).Hash
        $fixed=[datetime]::new(2001,1,1,0,0,0,[DateTimeKind]::Utc)
        [IO.File]::SetLastWriteTimeUtc($output,$fixed)
        & $generator -Registry $path -Process $process -Language Zig -Names $names -Output $output
        Assert-True ((Get-FileHash $output).Hash -ceq $hash -and [IO.File]::GetLastWriteTimeUtc($output) -eq $fixed) "Deterministic Zig output $process names=$names."
        foreach ($entry in (Get-Fixture).entries) {
            # @"name" is a Zig identifier, not a runtime string literal.
            $namePattern='(?<!@)"' + [regex]::Escape($entry.name) + '"'
            if (-not $names -or ($entry.process -cne $process -and $entry.name -cnotin @((Get-Fixture).entries | Where-Object process -CEQ $process | ForEach-Object name))) { Assert-True (-not [regex]::IsMatch($source,$namePattern)) 'No unwanted entry name string.' }
            Assert-True (-not $source.Contains(($entry.comment | ConvertTo-Json -Compress))) 'Comments are not in the Zig contract.'
        }
        $backend=$process -ceq 'backend'
        $root=if($backend){1}else{2}
        $child=if($backend){3}else{5}
        $item=if($backend){6}else{8}
        $perItem=if($backend){7}else{9}
        $lower=if($backend){10}else{14}
        $top=if($backend){11}else{15}
        $per=if($backend){12}else{16}
        $blockCount=if($backend){3}else{2}
        $conditionCount=if($backend){4}else{3}
        $firstStorage=if($backend){'reference'}else{'own'}
        $secondStorage=if($backend){'own'}else{'reference'}
        $firstOwner=if($backend){'1'}else{'null'}
        $secondOwner=if($backend){'null'}else{'2'}
        $secondTrigger=if($backend){'poll'}else{'event'}
        $nameCheck=if($names){'try std.testing.expectEqualStrings("Program", r.blocks[0].name.?); for (r.items) |i| try std.testing.expect(i.name != null); for (r.conditions) |c| try std.testing.expect(c.name != null);'}else{'for (r.blocks) |b| try std.testing.expect(b.name == null); for (r.items) |i| try std.testing.expect(i.name == null); for (r.conditions) |c| try std.testing.expect(c.name == null);'}
        $perCheck=if($backend){'try std.testing.expectEqual(@as(u32, 7), r.conditions[2].items[0].item); try std.testing.expect(r.conditions[2].items[0].block == null); try std.testing.expectEqual(@as(?u32, 3), r.conditions[3].items[0].block); try std.testing.expectEqual(@as(u32, 6), r.conditions[3].items[1].item); try std.testing.expectEqual(@as(u32, 12), g.ConditionUids.@"defer");'}else{'try std.testing.expectEqual(@as(usize, 0), r.conditions[2].items.len);'}
        $probe=@"
const std = @import("std");
const g = @import("generated");
const d = @import("rm_control").declarations;
test "generated declaration values" {
    const r: d.Registry = g.registry;
    try std.testing.expectEqualStrings("$process", r.process);
    try std.testing.expectEqualStrings("$(Get-StateRegistryVersion ([IO.File]::ReadAllBytes($path)))", r.version);
    try std.testing.expectEqual(@as(usize, $blockCount), r.blocks.len);
    try std.testing.expectEqual(@as(usize, 2), r.items.len);
    try std.testing.expectEqual(@as(usize, $conditionCount), r.conditions.len);
    try std.testing.expectEqual(@as(u32, $root), g.BlockUids.Program);
    try std.testing.expectEqual(@as(u32, $perItem), g.ItemUids.Demand);
    try std.testing.expectEqual(@as(u32, $top), g.ConditionUids.ShouldRun);
    try std.testing.expectEqual(@as(u32, $item), r.items[0].uid);
    try std.testing.expectEqual(d.ValueType.bool, r.items[0].value_type);
    try std.testing.expectEqual(d.Storage.$firstStorage, r.items[0].storage);
    try std.testing.expectEqual(d.Storage.$secondStorage, r.items[1].storage);
    try std.testing.expectEqual(d.Trigger.event, r.items[0].trigger);
    try std.testing.expectEqual(d.Trigger.$secondTrigger, r.items[1].trigger);
    try std.testing.expectEqual(@as(?u32, $firstOwner), r.items[0].owner_block);
    try std.testing.expectEqual(@as(?u32, $secondOwner), r.items[1].owner_block);
    try std.testing.expectEqual(@as(u32, $lower), r.conditions[0].uid);
    try std.testing.expectEqual(@as(u32, $top), r.conditions[1].uid);
    try std.testing.expectEqual(@as(u32, $per), r.conditions[2].uid);
    try std.testing.expect(!r.items[0].per_block);
    try std.testing.expect(r.items[1].per_block);
    try std.testing.expectEqual(@as(?u32, $root), r.conditions[0].node);
    try std.testing.expectEqual(@as(?u32, null), r.conditions[0].decides);
    try std.testing.expectEqual(@as(u32, $perItem), r.conditions[0].items[1].item);
    try std.testing.expectEqual(@as(?u32, $child), r.conditions[0].items[1].block);
    try std.testing.expectEqual(@as(u32, $lower), r.conditions[1].conditions[0]);
    try std.testing.expectEqual(@as(u32, $child), r.conditions[1].children[0]);
    try std.testing.expectEqual(@as(?u32, $child), r.conditions[1].decides);
    try std.testing.expect(r.conditions[2].per_block and r.conditions[2].node == null and r.conditions[2].decides == null);
    $nameCheck
    $perCheck
}
"@
        $probePath=Join-Path $scratch 'probe.zig'
        [IO.File]::WriteAllText($probePath,$probe)
        $zigArgs=@('test','-j1','-ODebug','--cache-dir',(Join-Path $scratch 'cache'),'--global-cache-dir',(Join-Path $scratch 'global-cache'),'--dep','generated','--dep','rm_control',"-Mroot=$probePath",'--dep','rm_control',"-Mgenerated=$output",('-Mrm_control='+(Join-Path $scratch 'rm_control.zig')))
        & $Zig @zigArgs
        Assert-True ($LASTEXITCODE -eq 0) "Zig compile and value test: $process names=$names."
    }
}
# A type other than bool generates a host-valued item: the value stays with its owner in the host.
$hostPath=Join-Path $scratch 'registry-host.json'
Write-StateRegistry $hostPath $otherType
$hostOutput=Join-Path $scratch 'backend-host.zig'
& $generator -Registry $hostPath -Process backend -Language Zig -Names $false -Output $hostOutput
$hostProbe=Join-Path $scratch 'host-probe.zig'
[IO.File]::WriteAllText($hostProbe,@"
const std = @import("std");
const g = @import("generated");
const d = @import("rm_control").declarations;
test "non-bool types are host-valued" {
    const r: d.Registry = g.registry;
    try std.testing.expectEqual(@as(u32, 6), r.items[0].uid);
    try std.testing.expectEqual(d.ValueType.host, r.items[0].value_type);
    try std.testing.expectEqual(d.ValueType.bool, r.items[1].value_type);
}
"@)
& $Zig test -j1 -ODebug --cache-dir (Join-Path $scratch 'cache') --global-cache-dir (Join-Path $scratch 'global-cache') --dep generated --dep rm_control "-Mroot=$hostProbe" --dep rm_control "-Mgenerated=$hostOutput" ('-Mrm_control='+(Join-Path $scratch 'rm_control.zig'))
Assert-True ($LASTEXITCODE -eq 0) 'Zig compile and value test: non-bool item is host.'
# The production registry generates Zig tables that compile for every process, whatever item types it holds.
foreach ($process in @('backend','ui','desktop','window')) {
    $productionOutput=Join-Path $scratch "$process-production.zig"
    & $generator -Registry (Join-Path $repo 'src/Shared/StateItems/state-items.json') -Process $process -Language Zig -Names $true -Output $productionOutput
    $productionProbe=Join-Path $scratch "$process-production-probe.zig"
    [IO.File]::WriteAllText($productionProbe,@"
const std = @import("std");
const g = @import("generated");
const d = @import("rm_control").declarations;
test "production tables compile" {
    const r: d.Registry = g.registry;
    try std.testing.expectEqualStrings("$process", r.process);
}
"@)
    & $Zig test -j1 -ODebug --cache-dir (Join-Path $scratch 'cache') --global-cache-dir (Join-Path $scratch 'global-cache') --dep generated --dep rm_control "-Mroot=$productionProbe" --dep rm_control "-Mgenerated=$productionOutput" ('-Mrm_control='+(Join-Path $scratch 'rm_control.zig'))
    Assert-True ($LASTEXITCODE -eq 0) "Production Zig tables compile: $process."
}
foreach ($process in @('backend','ui')) {
    $fixtureOutput=Join-Path $scratch "$process-fixture.cs"
    & $generator -Registry $path -Process $process -Namespace "FixtureConditions_$process" -Output $fixtureOutput
    $source=[IO.File]::ReadAllText($fixtureOutput)
    foreach ($names in @($true,$false)) {
        $ns='FixtureConditions_'+$process+'_'+$names
        $compiled=$source.Replace('using ResourceManager.Shared.BusinessBlocks.State;', "using $ns.SharedState;").Replace("namespace FixtureConditions_$process;", "namespace $ns {")
        $state=[IO.File]::ReadAllText((Join-Path $repo 'src/Shared/BusinessBlocks/State/StateRead.cs')).Replace('namespace ResourceManager.Shared.BusinessBlocks.State;', "namespace $ns.SharedState {")
        $options=if($names){@('/define:RM_STATE_NAMES')}else{@('/optimize')}
        $types=Add-Type -TypeDefinition ("using System;" + $compiled + "}" + $state + "}") -CompilerOptions $options -PassThru
        $assembly=$types[0].Assembly
        $top=if($process -ceq 'backend'){11}else{15}
        Assert-True ($assembly.GetType("$ns.ConditionUids").GetField('ShouldRun').GetRawConstantValue() -eq $top) 'CSharp condition UID compiles correctly.'
        $nameType=$assembly.GetType("$ns.StateNames")
        Assert-True (($null -ne $nameType) -eq $names) 'CSharp condition names follow the compile switch.'
        if ($names) { Assert-True ($nameType.GetMethod('Name').Invoke($null,@([int]$top)) -ceq 'ShouldRun') 'CSharp resolves condition names.' }
    }
}
foreach ($process in @(if ($CSharpBaselineDirectory) { 'backend','ui' })) {
    $output=Join-Path $scratch "$process-production.cs"
    & $generator -Registry (Join-Path $repo 'src/Shared/StateItems/state-items.json') -Process $process -Namespace ResourceManager -Output $output
    $baseline=Join-Path $CSharpBaselineDirectory "$process.before.cs"
    Assert-True ([Convert]::ToBase64String([IO.File]::ReadAllBytes($output)) -ceq [Convert]::ToBase64String([IO.File]::ReadAllBytes($baseline))) "Production C# $process bytes unchanged from before implementation."
}
"Passed $script:count assertions; 9 Zig 0.17.0 compile/value tests. Fixtures: $scratch"
